-- Stage only after frontend MFA enrollment and verification have been tested.
create schema if not exists opsboard_private;
revoke all on schema opsboard_private from public,anon,authenticated;
create function opsboard_private.require_mfa() returns void language plpgsql security invoker set search_path='' as $$ begin
if auth.uid() is null or coalesce(auth.jwt()->>'aal','') <> 'aal2' then raise exception 'Multi-factor authentication required' using errcode='42501'; end if;
end $$;
revoke all on function opsboard_private.require_mfa() from public,anon,authenticated;
alter function public.my_organizations() set schema opsboard_private;
revoke all on function opsboard_private.my_organizations() from public,anon,authenticated;
create function public.my_organizations() returns jsonb language plpgsql security definer set search_path='' as $$ begin perform opsboard_private.require_mfa(); return opsboard_private.my_organizations(); end $$;
revoke all on function public.my_organizations() from public,anon;
grant execute on function public.my_organizations() to authenticated;
alter function public.create_organization(text) set schema opsboard_private;
revoke all on function opsboard_private.create_organization(text) from public,anon,authenticated;
create function public.create_organization(org_name text) returns uuid language plpgsql security definer set search_path='' as $$ begin perform opsboard_private.require_mfa(); return opsboard_private.create_organization(org_name); end $$;
revoke all on function public.create_organization(text) from public,anon;
grant execute on function public.create_organization(text) to authenticated;
