create function public.invite_workspace_member(org uuid,invite_email text,invite_role text) returns uuid language plpgsql security definer set search_path='' as $$ begin perform opsboard_private.require_mfa(); return opsboard_private.invite_workspace_member(org,invite_email,invite_role); end $$;
revoke all on function public.invite_workspace_member(uuid,text,text) from public,anon;
