create function public.revoke_workspace_invitation(org uuid,invitation uuid) returns void language plpgsql security definer set search_path='' as $$ begin perform opsboard_private.require_mfa(); perform opsboard_private.revoke_workspace_invitation(org,invitation); return; end $$;
revoke all on function public.revoke_workspace_invitation(uuid,uuid) from public,anon;
